static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }
    int year = (int) (timeBucket / 10000);
    int month = (int) ((timeBucket % 10000) / 100);
    int day = (int) (timeBucket % 100);

    // Calculate the first day of the month
    int firstDayOfMonth = 1;

    // Calculate the number of days in the month
    int daysInMonth;
    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            daysInMonth = 31;
            break;
        case 4: case 6: case 9: case 11:
            daysInMonth = 30;
            break;
        case 2:
            if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
                daysInMonth = 29; // Leap year
            } else {
                daysInMonth = 28;
            }
            break;
        default:
            throw new IllegalArgumentException("Invalid month in timeBucket");
    }

    // Find the closest day that is a multiple of dayStep
    int adjustedDay = firstDayOfMonth + (day - firstDayOfMonth) / dayStep * dayStep;
    if (adjustedDay + dayStep > daysInMonth) {
        adjustedDay -= dayStep;
    }

    return year * 10000L + month * 100L + adjustedDay;
}

int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Invalid index or length");
    }
    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < index + len) {
                char nextChar = str.charAt(i + 1);
                if (Character.isLowSurrogate(nextChar)) {
                    size += 4; // surrogate pair
                    i++; // skip the next character as it is part of the surrogate pair
                } else {
                    throw new IllegalArgumentException("Invalid surrogate pair");
                }
            } else {
                throw new IllegalArgumentException("Invalid surrogate pair");
            }
        } else {
            size += 3;
        }
    }
    return size;
}

