        return 2;
    }
    int maxCapacity = desiredCapacity;
    if (desiredCapacity >= 1000) {
        maxCapacity = (int) (desiredCapacity * 1.11);
    }
    for (int i = desiredCapacity; i <= maxCapacity; i++) {
        if (isPrime(i)) {
            return i;
        }
    }
    return maxCapacity; // Fallback, should not reach here if input is valid
}

private static boolean isPrime(int num) {
    if (num <= 1) {
        return false;
    }
    if (num <= 3) {
        return true;
    }
    if (num % 2 == 0 || num % 3 == 0) {
        return false;
    }
    for (int i = 5; i * i <= num; i += 6) {
        if (num % i == 0 || num % (i + 2) == 0) {
            return false;
        }
    }
    return true;
}

