public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < str.length()) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= str.length()) {
                throw new Exception("Invalid escape sequence at end of string");
            }
            char nextChar = str.charAt(i + 1);
            switch (nextChar) {
                case 'b':
                    result.append('\b');
                    break;
                case 't':
                    result.append('\t');
                    break;
                case 'n':
                    result.append('\n');
                    break;
                case 'f':
                    result.append('\f');
                    break;
                case 'r':
                    result.append('\r');
                    break;
                case '"':
                    result.append('"');
                    break;
                case '\'':
                    result.append('\'');
                    break;
                case '\\':
                    result.append('\\');
                    break;
                case 'u':
                    if (i + 5 >= str.length()) {
                        throw new Exception("Invalid Unicode escape sequence");
                    }
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int value = Integer.parseInt(hex, 16);
                        result.append((char) value);
                        i += 5; // Skip the hex digits
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid Unicode escape sequence: " + hex);
                    }
                    break;
                default:
                    throw new Exception("Invalid escape sequence: \\" + nextChar);
            }
            i += 2; // Skip the escape character and the next character
        } else {
            result.append(c);
            i++;
        }
    }
    return result.toString();
}

