final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    try {
        if (constantPoolEntryIndex < 1 || constantPoolEntryIndex >= classFileBuffer.length) {
            throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
        }
        if (charBuffer == null) {
            throw new IllegalArgumentException("Character buffer cannot be null");
        }

        int pos = constantPoolEntryIndex;
        int tag = classFileBuffer[pos++] & 0xFF;
        if (tag != 1) { // CONSTANT_Utf8 tag
            throw new IllegalArgumentException("Constant pool entry at index " + constantPoolEntryIndex + " is not a CONSTANT_Utf8");
        }

        int length = ((classFileBuffer[pos++] & 0xFF) << 8) | (classFileBuffer[pos++] & 0xFF);
        if (length > charBuffer.length) {
            throw new IllegalArgumentException("Character buffer is not large enough to hold the string");
        }

        for (int i = 0; i < length; i++) {
            charBuffer[i] = (char) ((classFileBuffer[pos++] & 0xFF) << 8 | (classFileBuffer[pos++] & 0xFF));
        }

        return new String(charBuffer, 0, length);
    } catch (ArrayIndexOutOfBoundsException e) {
        throw new RuntimeException("Unexpected end of class file buffer", e);
    }
}

