public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path cannot be null");
    }

    // Normalize the paths by removing trailing slashes
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }
    if (relativePath.startsWith("/")) {
        relativePath = relativePath.substring(1);
    }

    // Split the paths into components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Process the relative path components
    int pathIndex = pathComponents.length - 1;
    for (String component : relativePathComponents) {
        if (component.equals("..")) {
            if (pathIndex > 0) {
                pathIndex--;
            }
        } else if (!component.equals(".")) {
            // Add the component to the path
            pathComponents = Arrays.copyOf(pathComponents, pathIndex + 2);
            pathComponents[++pathIndex] = component;
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    for (int i = 0; i <= pathIndex; i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(pathComponents[i]);
    }

    return result.toString();
}

